class Solution { void propagate(int m,int c,int turn,int childResult,vector<vector<array<int,2>>>& outcome,vector<vector<array<int,2>>>& degree,queue<array<int,4>>& pending){if(outcome[m][c][turn])return;int playerWin=turn==0?1:2;if(childResult==playerWin){outcome[m][c][turn]=childResult;pending.push({m,c,turn,childResult});}else if(--degree[m][c][turn]==0){int result=turn==0?2:1;outcome[m][c][turn]=result;pending.push({m,c,turn,result});}}public:int catMouseGame(vector<vector<int>>& graph){int n=graph.size();vector<vector<array<int,2>>> outcome(n,vector<array<int,2>>(n,{0,0})),degree(n,vector<array<int,2>>(n,{0,0}));for(int m=0;m<n;++m)for(int c=1;c<n;++c){degree[m][c][0]=graph[m].size();for(int next:graph[c])degree[m][c][1]+=next!=0;}queue<array<int,4>> pending;for(int c=1;c<n;++c)for(int turn=0;turn<2;++turn){outcome[0][c][turn]=1;pending.push({0,c,turn,1});}for(int m=1;m<n;++m)for(int turn=0;turn<2;++turn){outcome[m][m][turn]=2;pending.push({m,m,turn,2});}while(!pending.empty()){auto state=pending.front();pending.pop();int m=state[0],c=state[1],turn=state[2],result=state[3];if(turn==0){for(int previousCat:graph[c])if(previousCat)propagate(m,previousCat,1,result,outcome,degree,pending);}else for(int previousMouse:graph[m])propagate(previousMouse,c,0,result,outcome,degree,pending);}return outcome[1][2][0];} };
